package wirestack_m8_001_consumer

import wirestack.net.*
import wirestack as api

main(): Int64 {
    println("BOOT")
    let _ = readln()
    let endpoint = api.SocketEndpoint(
        api.IpAddress(api.IpAddressFamily.Ipv4, [127u8, 0u8, 0u8, 1u8]), 9u16)
    try {
        let warm = TcpStream.connect(endpoint, context: api.OperationContext(
            deadline: Some(api.Deadline.after(200 * Duration.millisecond))))
        warm.close()
    } catch (_: Exception) {}
    println("READY")
    let _ = readln()
    try {
        let stream = TcpStream.connect(endpoint, context: api.OperationContext(
            deadline: Some(api.Deadline.after(Duration.second))))
        stream.close()
        println("UNEXPECTED_CONNECT_SUCCESS")
        return 2
    } catch (error: api.NetworkException) {
        let classification = match ((error.category, error.phase, error.code)) {
            case (api.NetworkErrorCategory.Connect, api.NetworkPhase.TcpConnect,
                api.NetworkErrorCode.SystemFailure) => true
            case _ => false
        }
        let peer = match (error.remoteEndpoint) {
            case Some(api.NetworkEndpoint.Internet(value)) => value.port == 9u16
            case _ => false
        }
        if (!classification || !peer || error.cause.isNone()) {
            println("INCOMPLETE_CONNECT_DIAGNOSTICS")
            return 3
        }
        println("MAPPED_CONSTRUCTION_FAILURE")
        return 0
    } catch (error: Exception) {
        println("UNMAPPED_CONSTRUCTION_FAILURE: ${error.toString()}")
        return 42
    }
}
